<div class="repeater-item day-item"><div class="repeater-head"><h3>วันเดินทาง <span class="day-number"><?= is_numeric($i) ? $i+1 : '' ?></span></h3><div><button type="button" class="icon-btn" data-move="up" aria-label="เลื่อนวันขึ้น">↑</button><button type="button" class="icon-btn" data-move="down" aria-label="เลื่อนวันลง">↓</button><button type="button" class="text-button danger" data-remove>นำวันออก</button></div></div><div class="stack-form"><label>หัวข้อประจำวัน<input name="itinerary[<?= $i ?>][title]" maxlength="200" value="<?= e($day['title'] ?? '') ?>"></label><label>สถานที่และกิจกรรม<textarea name="itinerary[<?= $i ?>][description]" rows="3" maxlength="10000"><?= e($day['description'] ?? '') ?></textarea></label><?php load_view('admin/day_photo_fields',['i'=>$i,'day'=>$day]); ?><label>ที่พักคืนนี้ / ประเภทห้อง<input name="itinerary[<?= $i ?>][hotel]" maxlength="200" value="<?= e($day['hotel'] ?? '') ?>" placeholder="ระบุชื่อโรงแรม หรือเทียบเท่า"></label><?php load_view('admin/day_hotel_fields',['i'=>$i,'day'=>$day]); ?><div class="meal-row"><b>มื้ออาหารที่รวม:</b><?php foreach (['breakfast'=>'เช้า','lunch'=>'กลางวัน','dinner'=>'เย็น'] as $f=>$label): ?><label><?= $label ?><select name="itinerary[<?= $i ?>][<?= $f ?>]"><?php foreach ([''=>'ไม่ระบุ','1'=>'รวม','0'=>'ไม่รวม'] as $value=>$text): ?><option value="<?= $value ?>" <?= (string)($day[$f] ?? '')===(string)$value ? 'selected' : '' ?>><?= $text ?></option><?php endforeach ?></select></label><?php endforeach ?></div></div></div>
